mapper.select:


    and l.courtyard_id = #{courtyardId}
    and l.main_type = #{mainType}
    and l.sub_type = #{subType}
    and l.inspect_result = #{inspectResult}
    and l.hazard_level = #{hazardLevel}
    and l.create_by = #{createBy}
    and l.address_name like concat('%', #{addressName}, '%')
    and l.inspect_time >= #{beginTime}
    and l.inspect_time <= #{endTime}

order by l.inspect_time desc

select l.courtyard_id, c.courtyard_name as courtyard_name, count(*) as total_count, sum(case when l.inspect_result = 'hazard' then 1 else 0 end) as hazard_count, sum(case when l.inspect_result = 'rectified' then 1 else 0 end) as rectified_count from ins_log l left join ins_courtyard c on l.courtyard_id = c.courtyard_id
and l.inspect_time >= #{beginTime} and l.inspect_time <= #{endTime}
group by l.courtyard_id, c.courtyard_name


where l.tenant_name is not null and l.tenant_name != ''
and l.courtyard_id = #{courtyardId}
order by l.inspect_time desc

mapper.update:
update ins_log
address_name = #{addressName}, main_type = #{mainType}, sub_type = #{subType}, inspect_result = #{inspectResult}, hazard_level = #{hazardLevel}, description = #{description}, tenant_name = #{tenantName}, tenant_phone = #{tenantPhone}, update_by = #{updateBy}, update_time = sysdate()
where log_id = #{logId}
